// the blueprint: a new data type named Student
struct Student {
    int id;          // data member 1
    string name;     // data member 2
    double cgpa;     // data member 3
};                   // <- semicolon is required

// a variable of that type = one record
Student s1;

// reach one member with the dot operator
s1.cgpa = 3.5;

sample.code:
#include <iostream>
#include <string>
using namespace std;

int main() {
    int id[3] = {1, 2, 3};
    string name[3] = {"Ali", "Sana", "Usman"};
    double cgpa[3] = {3.5, 3.9, 2.8};
    // swap student 0 and student 2: three arrays, three swaps
    int t1 = id[0]; id[0] = id[2]; id[2] = t1;
    string t2 = name[0]; name[0] = name[2]; name[2] = t2;
    double t3 = cgpa[0]; cgpa[0] = cgpa[2]; cgpa[2] = t3;
    for (int i = 0; i < 3; i++) {
        cout << id[i] << " " << name[i] << " " << cgpa[i] << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    int id;
    string name;
    double cgpa;
};

int main() {
    Student a = {1, "Ali", 3.5};
    Student b = {3, "Usman", 2.8};
    Student t = a;
    a = b;
    b = t;
    cout << a.id << " " << a.name << " " << a.cgpa << endl;
    cout << b.id << " " << b.name << " " << b.cgpa << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Book {
    string title;
    int pages;
    double price;
};

int main() {
    Book b1 = {"C++ Basics", 320, 850.5};
    Book b2 = {"Data Notes", 150, 600};
    Book dearer = b1;
    if (b2.price > b1.price) {
        dearer = b2;
    }
    cout << "Costlier: " << dearer.title << " (Rs " << dearer.price << ")" << endl;
    cout << "Pages: " << dearer.pages << endl;
    return 0;
}

